    30	type IsEnoughSpaceToRenderMenuAboveCursor = Pick<MeasureParentContainerAndCursor, 'y' | 'cursorCoordinates' | 'scrollValue'> & {
    31	    contentHeight: number;
    32	    topInset: number;
    33	};
    34	function isEnoughSpaceToRenderMenuAboveCursor({y, cursorCoordinates, scrollValue, contentHeight, topInset}: IsEnoughSpaceToRenderMenuAboveCursor): boolean {
    35	    return y + (cursorCoordinates.y - scrollValue) > contentHeight + topInset + CONST.AUTO_COMPLETE_SUGGESTER.SUGGESTION_BOX_MAX_SAFE_DISTANCE;
    36	}
    37	
    38	const initialContainerState = {
    39	    width: 0,
    40	    left: 0,
    41	    bottom: 0,
    42	    cursorCoordinates: {x: 0, y: 0},
    43	};
    44	
    45	/**
    46	 * On the mobile-web platform, when long-pressing on auto-complete suggestions,
    47	 * we need to prevent focus shifting to avoid blurring the main input (which makes the suggestions picker close and fires the onSelect callback).
    48	 * The desired pattern for all platforms is to do nothing on long-press.
    49	 * On the native platform, tapping on auto-complete suggestions will not blur the main input.
    50	 */
    51	function AutoCompleteSuggestions<TSuggestion>({measureParentContainerAndReportCursor = () => {}, ...props}: AutoCompleteSuggestionsProps<TSuggestion>) {
    52	    const containerRef = React.useRef<HTMLDivElement>(null);
    53	    const isInitialRender = React.useRef<boolean>(true);
    54	    const isSuggestionMenuAboveRef = React.useRef<boolean>(false);
    55	    const leftValue = React.useRef<number>(0);
    56	    const prevLeftValue = React.useRef<number>(0);
    57	    const {windowHeight, windowWidth} = useWindowDimensions();
    58	    const {shouldUseNarrowLayout} = useResponsiveLayout();
    59	    const [suggestionHeight, setSuggestionHeight] = React.useState(0);
    60	    const [containerState, setContainerState] = React.useState(initialContainerState);
    61	    const StyleUtils = useStyleUtils();
    62	    const insets = useSafeAreaInsets();
    63	    const {keyboardHeight} = useKeyboardState();
    64	    const {paddingBottom: bottomInset, paddingTop: topInset} = StyleUtils.getSafeAreaPadding(insets ?? undefined);
    65	
    66	    useEffect(() => {
    67	        const container = containerRef.current;
    68	        if (!container) {
    69	            return () => {};
    70	        }
    71	        container.onpointerdown = (e) => {
    72	            if (DeviceCapabilities.hasHoverSupport()) {
    73	                return;
    74	            }
    75	            e.preventDefault();
    76	        };
    77	        return () => (container.onpointerdown = null);
    78	    }, []);
    79	
    80	    const suggestionsLength = props.suggestions.length;
    81	
    82	    useEffect(() => {
    83	        if (!measureParentContainerAndReportCursor) {
    84	            return;
    85	        }
    86	
    87	        if (!windowHeight || !windowWidth || !suggestionsLength) {
    88	            setContainerState(initialContainerState);
    89	            return;
    90	        }
    91	
    92	        measureParentContainerAndReportCursor(({x, y, width, scrollValue, cursorCoordinates}: MeasureParentContainerAndCursor) => {
    93	            const xCoordinatesOfCursor = x + cursorCoordinates.x;
    94	            const bigScreenLeftOffset =
    95	                xCoordinatesOfCursor + CONST.AUTO_COMPLETE_SUGGESTER.BIG_SCREEN_SUGGESTION_WIDTH > windowWidth
    96	                    ? windowWidth - CONST.AUTO_COMPLETE_SUGGESTER.BIG_SCREEN_SUGGESTION_WIDTH
    97	                    : xCoordinatesOfCursor;
    98	            const contentMaxHeight = measureHeightOfSuggestionRows(suggestionsLength, true);
    99	            const contentMinHeight = measureHeightOfSuggestionRows(suggestionsLength, false);
   100	            let bottomValue = windowHeight - (cursorCoordinates.y - scrollValue + y) - keyboardHeight;
   101	            const widthValue = shouldUseNarrowLayout ? width : CONST.AUTO_COMPLETE_SUGGESTER.BIG_SCREEN_SUGGESTION_WIDTH;
   102	
   103	            const isEnoughSpaceToRenderMenuAboveForBig = isEnoughSpaceToRenderMenuAboveCursor({y, cursorCoordinates, scrollValue, contentHeight: contentMaxHeight, topInset});
   104	            const isEnoughSpaceToRenderMenuAboveForSmall = isEnoughSpaceToRenderMenuAboveCursor({y, cursorCoordinates, scrollValue, contentHeight: contentMinHeight, topInset});
   105	
   106	            const newLeftOffset = shouldUseNarrowLayout ? x : bigScreenLeftOffset;
   107	            // If the suggested word is longer than 150 (approximately half the width of the suggestion popup), then adjust a new position of popup
   108	            const isAdjustmentNeeded = Math.abs(prevLeftValue.current - bigScreenLeftOffset) > 150;
   109	            if (isInitialRender.current || isAdjustmentNeeded) {
   110	                isSuggestionMenuAboveRef.current = isSuggestionMenuRenderedAbove(isEnoughSpaceToRenderMenuAboveForBig, isEnoughSpaceToRenderMenuAboveForSmall);
   111	                leftValue.current = newLeftOffset;
   112	                isInitialRender.current = false;
   113	                prevLeftValue.current = newLeftOffset;
   114	            }
   115	
   116	            let measuredHeight = 0;
   117	            if (isSuggestionMenuAboveRef.current && isEnoughSpaceToRenderMenuAboveForBig) {
