   120	            } else if (isSuggestionMenuAboveRef.current && isEnoughSpaceToRenderMenuAboveForSmall) {
   121	                // calculation for small suggestion box above the cursor
   122	                measuredHeight = measureHeightOfSuggestionRows(suggestionsLength, false);
   123	            } else {
   124	                // calculation for big suggestion box below the cursor
   125	                measuredHeight = measureHeightOfSuggestionRows(suggestionsLength, true);
   126	                bottomValue = windowHeight - y - cursorCoordinates.y + scrollValue - measuredHeight - CONST.AUTO_COMPLETE_SUGGESTER.SUGGESTION_ROW_HEIGHT - keyboardHeight;
   127	            }
   128	            setSuggestionHeight(measuredHeight);
   129	            setContainerState({
   130	                left: leftValue.current,
   131	                bottom: bottomValue,
   132	                width: widthValue,
   133	                cursorCoordinates,
   134	            });
   135	        });
   136	    }, [measureParentContainerAndReportCursor, windowHeight, windowWidth, keyboardHeight, shouldUseNarrowLayout, suggestionsLength, bottomInset, topInset]);
   137	
