   142	        <AutoCompleteSuggestionsPortal
   143	            // eslint-disable-next-line react/jsx-props-no-spreading
   144	            {...props}
   145	            left={containerState.left}
   146	            width={containerState.width}
   147	            bottom={containerState.bottom}
   148	            measuredHeightOfSuggestionRows={suggestionHeight}
   149	        />
   150	    );
   151	}
